"""Build the final report and separate CNN supplement from measured run artifacts."""
from pathlib import Path
import argparse, json, re
from xml.sax.saxutils import escape
import numpy as np
import pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, Image, PageBreak
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.pagesizes import A4

ROOT=Path(__file__).resolve().parent
OUT=ROOT/'output'/'pdf'
FIG=ROOT/'outputs'/'figures'
KEYS=['logistic_regression','svm','knn','decision_tree','random_forest','gradient_boosting']
ST=getSampleStyleSheet()
ST.add(ParagraphStyle(name='SmallText',fontSize=8,leading=10,spaceAfter=5))
ST['BodyText'].fontSize=10; ST['BodyText'].leading=14; ST['BodyText'].spaceAfter=8
ST['Title'].textColor=colors.HexColor('#174c48')
ST['Heading1'].textColor=colors.HexColor('#174c48')

def read(path): return json.loads(path.read_text(encoding='utf-8'))
def p(text,style='BodyText'): return Paragraph(escape(str(text)).replace('\n','<br/>'), ST[style])
def table(rows,widths=None):
    cells=[[p(x,'SmallText') for x in row] for row in rows]
    t=Table(cells,colWidths=widths,repeatRows=1,hAlign='LEFT')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#dfefec')),('VALIGN',(0,0),(-1,-1),'TOP'),('LINEBELOW',(0,0),(-1,0),0.7,colors.HexColor('#174c48')),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#f5f8f8')]),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4)]))
    return t
def pic(path,width=490):
    from PIL import Image as PILImage
    with PILImage.open(path) as im: height=width*im.height/im.width
    return Image(str(path),width=width,height=height)
def footer(canvas,doc):
    canvas.setFont('Helvetica',8); canvas.setFillColor(colors.HexColor('#526563'))
    canvas.drawString(42,25,'IT2011 | Basil leaf quality classification | Group '+GROUP)
    canvas.drawRightString(A4[0]-42,25,str(doc.page))
def build(path,story):
    SimpleDocTemplate(str(path),pagesize=A4,rightMargin=42,leftMargin=42,topMargin=36,bottomMargin=42,title=GROUP,author='Group '+GROUP).build(story,onFirstPage=footer,onLaterPages=footer)
def page(story,title):
    if story: story.append(PageBreak())
    story.append(p(title,'Heading1'))
def savefig(name):
    plt.tight_layout(); plt.savefig(FIG/name,dpi=180,bbox_inches='tight'); plt.close()

def main(group, classical_only=False):
    global GROUP
    GROUP=group
    OUT.mkdir(parents=True,exist_ok=True); FIG.mkdir(parents=True,exist_ok=True)
    summary=read(ROOT/'outputs'/'results.json')
    metrics={k:read(ROOT/'parts'/k/'outputs'/f'{k}_metrics.json') for k in KEYS}
    fingerprint=summary['dataset_fingerprint']
    if any(m['dataset_fingerprint']!=fingerprint for m in metrics.values()): raise ValueError('Mixed dataset runs')
    cmp=pd.read_csv(ROOT/'outputs'/'six_model_comparison.csv')
    if len(cmp)!=6 or set(cmp.model)!=set(m['model_name'] for m in metrics.values()): raise ValueError('Expected exactly six models')
    manifest=pd.read_csv(ROOT/'outputs'/'split_manifest.csv')
    audit=summary['data_audit']
    fig,ax=plt.subplots(1,2,figsize=(10,3.2))
    pd.crosstab(manifest.label,manifest.split).plot.bar(ax=ax[0],rot=0,color=['#23877b','#e1a843'])
    ax[0].set(title='Class distribution by split',ylabel='Unique images',xlabel='')
    manifest.assign(folder=manifest.path.str.split('/').str[0]).groupby('folder').size().rename(index=lambda s:s.replace('_Region_Basil_Plant_Healthy',' Healthy').replace('Basil_Plant_Unhealthy','Unhealthy')).plot.barh(ax=ax[1],color='#23877b')
    ax[1].set(title='Source folder distribution',xlabel='Unique images',ylabel='')
    savefig('dataset_eda.png')
    fig,ax=plt.subplots(figsize=(9,3.5)); x=np.arange(6)
    ax.bar(x-.18,cmp.cv_macro_f1,.36,label='Development CV',color='#23877b')
    ax.bar(x+.18,cmp.macro_f1,.36,label='Holdout',color='#e1a843')
    ax.set(xticks=x,xticklabels=[s.replace(' ','\n') for s in cmp.model],ylim=(0,1.05),ylabel='Macro-F1',title='Six classical models - CNN excluded'); ax.legend(loc='lower right')
    savefig('six_model_comparison.png')
    story=[]
    story.extend([Spacer(1,32),p(group,'Title'),p('Final Evaluation - Group Report','Title'),p('Basil Leaf Quality Classification','Heading1'),p('IT2011 - Artificial Intelligence and Machine Learning\nFaculty of Computing | Year 2, Semester 1 (2026)'),Spacer(1,12),p('1. Introduction and Problem Statement','Heading1'),p('The task is to distinguish Healthy and Unhealthy basil leaf photographs using the assigned image dataset. The intended output is an experimental image label for an uploaded leaf photograph. It does not identify a specific disease, establish food safety or replace an agricultural assessment.'),p('The group compares six classical supervised models: Logistic Regression, SVM, KNN, Decision Tree, Random Forest and Gradient Boosting. Each has a complete raw-image-to-prediction notebook and independently tuned settings. CNN is preserved as a separate supplementary experiment and excluded from this report\'s six-model ranking.'),p('Measured outcome','Heading2'),p(f"The development-validation-selected model is {summary['selected_model']}. Its holdout accuracy is {summary['metrics']['accuracy']:.2%} and macro-F1 is {summary['metrics']['macro_f1']:.4f}. This selection uses validation scores, not the best holdout score."),p('Scope and evidence','Heading2'),p('This report is generated from actual saved tuning tables, predictions, split manifests and metrics. It follows the nine sections requested in the supplied final-evaluation documentation. Historical progress work remains under progress/. No individual contribution or personal reflection is invented.'),p('Assessment caveat','Heading2'),p('The fixed holdout was already evaluated in earlier project runs. It is excluded from the current search but must be described as a reused holdout, not a new external test. New-plant and new-location testing is still required.')])
    page(story,'2. Dataset Description / 3. Preprocessing and EDA')
    story.extend([p("Assigned source: Leaves - India's Most Famous Basil Plant Leaves Quality Dataset, IEEE DataPort, DOI 10.21227/a4f6-4413. The local project records this attribution; the source landing page was not retrievable during report preparation."),table([['Audit item','Observed value'],['Listed image files',audit['input_count']],['Unique valid images',audit['valid_unique_count']],['Exact duplicates removed',audit['exact_duplicates_removed']],['Rejected images',len(audit['rejected_images'])],['Perceptual groups',audit['split_groups']],['Development / holdout',f"{summary['development_images']} / {summary['test_images']}"]],[240,260]),Spacer(1,10),pic(FIG/'dataset_eda.png'),p('Figure 1. Class and source distributions after audit. Healthy examples come from three named regions, while unhealthy examples use one pooled folder. Health may therefore be confounded with source, background or capture conditions. Region-wise fairness cannot be estimated for unhealthy leaves from the available labels.','SmallText'),p('Images are decoded, EXIF-oriented, converted to RGB and validated. Duplicate decoded pixels are removed. Perceptual hashes within Hamming distance 4 are grouped before splitting. Grouping reduces similar-image leakage but does not establish independent plant identities.'),p('No image-content outliers are deleted solely because they appear unusual; disease patterns may be informative. No missing numeric values require imputation. Historical progress PCA/scaled data are preserved but not reused for final fitting.')])
    page(story,'4. Model Design and Implementation')
    story.extend([p('Complete reproducible pipeline','Heading2'),p('Raw labelled folders -> validation and duplicate audit -> grouped holdout split -> handcrafted features -> three grouped development folds -> fold-local scaling and feature selection -> parameter search -> refit on development images -> holdout metrics, plots and serialized model -> image prediction.'),p('Feature representation','Heading2'),p('Every classical model receives the same 1,882-dimensional representation: 108 RGB/HSV histogram and summary features, 10 local binary pattern texture bins, and 1,764 HOG edge features. Color and texture use 128 x 128 images; HOG uses 64 x 64 grayscale. Fixed per-image feature extraction learns no dataset-level statistics.'),p('Validation and tuning protocol','Heading2'),p('Seed 42 fixes an approximately 80/20 StratifiedGroupKFold holdout. On development images, identical three-fold grouped splits are reused across models. StandardScaler and SelectPercentile(f_classif) are fitted inside each training fold. Every parameter combination is tested with all features and with the top 25% features. Test labels are never used to fit these operations.'),p('GridSearchCV selects maximum mean validation macro-F1 and refits on all development data. Accuracy and balanced accuracy are also logged for every candidate. Training scores and fold standard deviations expose overfitting and instability. Scores used for search selection are optimistic estimates, not nested-CV performance.'),table([['Model','Candidates','CV fits'],*[[m['model_name'],m['candidate_count'],m['cv_fits']] for m in metrics.values()]],[270,110,120]),Spacer(1,10),p('Metrics and uncertainty','Heading2'),p('Macro-F1 is the mean of class F1 scores; each class contributes equally. Accuracy measures overall correctness, while balanced accuracy averages class recall. Per-class precision/recall and confusion matrices reveal false-healthy predictions. A 500-resample group bootstrap estimates holdout macro-F1 uncertainty; it does not account for training-set or model-selection uncertainty.'),p('The following pages record every candidate variety and its validation outcome. Hyperparameters are limited to a practical CPU search, not an exhaustive global optimum.')])
    for key,m in metrics.items():
        page(story,'4. '+m['model_name']+' - individual pipeline')
        trials=pd.read_csv(ROOT/'parts'/key/'outputs'/'tuning_results.csv')
        fixed = {'logistic_regression':'scikit-learn LogisticRegression: balanced class weights, max_iter=4000.', 'svm':'scikit-learn SVC: RBF kernel, balanced class weights.', 'knn':'scikit-learn KNeighborsClassifier: Minkowski distance, p=2 (Euclidean).', 'decision_tree':'scikit-learn DecisionTreeClassifier: Gini criterion, balanced class weights.', 'random_forest':'scikit-learn RandomForestClassifier: 200 trees, Gini criterion, balanced class weights.', 'gradient_boosting':'scikit-learn GradientBoostingClassifier: 100 trees, max_features=sqrt, log-loss.'}[key]
        story.extend([p(m['rationale']),p(fixed,'SmallText'),p('Winning configuration: '+str(m['best_params']),'SmallText'),p(f"{m['candidate_count']} candidate varieties / {m['cv_fits']} validation fits. Best CV macro-F1 {m['cv_macro_f1']:.4f} (fold SD {m['cv_std']:.4f}); holdout accuracy {m['accuracy']:.2%}; holdout macro-F1 {m['macro_f1']:.4f}. Search and refit time: {m['tuning_seconds']:.1f} seconds.",'SmallText')])
        rows=[['ID','Parameter variety (model prefix omitted)','Train F1','CV F1','CV acc.']]
        import ast
        for i,row in trials.iterrows():
            params=ast.literal_eval(row['params'])
            desc=', '.join(f'{k.replace("model__", "").replace("select__percentile", "features %")}={v}' for k,v in params.items())
            rows.append([i,desc,f'{row.mean_train_f1:.3f}',f'{row.mean_test_f1:.3f}',f'{row.mean_test_accuracy:.3f}'])
        story.extend([table(rows,[24,282,60,60,65]),Spacer(1,8),pic(ROOT/'parts'/key/'outputs'/'evaluation.png'),p('Figure: training/validation scores across candidate settings and final holdout confusion matrix. Candidate IDs match tuning_results.csv. Rows are actual classes; columns are predicted classes.','SmallText')])
        reduced=trials[trials.param_select__percentile==25].mean_test_f1.max(); full=trials[trials.param_select__percentile==100].mean_test_f1.max()
        selected=trials.loc[trials.rank_test_f1.idxmin()]
        story.append(p(f'Conclusion: best reduced-feature CV F1 = {reduced:.4f}, versus {full:.4f} with all features. The selected candidate has a training-minus-validation F1 gap of {selected.mean_train_f1-selected.mean_test_f1:.4f}. Retain the validation-selected setting; improvement on new images is not guaranteed. The holdout contains {m["confusion_matrix"][1][0]} unhealthy leaves predicted healthy.','SmallText'))
    page(story,'5. Evaluation and Comparison - exactly six models')
    story.append(p('Models are ordered by development CV macro-F1. CNN is excluded. Each holdout column uses identical image paths and labels.'))
    story.append(table([['Model','CV F1','Test acc.','Test F1','95% group-bootstrap F1'],*[[row.model,f'{row.cv_macro_f1:.4f}',f'{row.accuracy:.2%}',f'{row.macro_f1:.4f}', ' - '.join(f'{x:.4f}' for x in next(m for m in metrics.values() if m['model_name']==row.model)['macro_f1_group_bootstrap_95_interval'])] for row in cmp.itertuples()]],[133,68,75,68,147]))
    story.extend([Spacer(1,10),pic(FIG/'six_model_comparison.png'),p('Figure 2. Validation and holdout macro-F1. Different rankings across the two sets are expected with limited data; the holdout ranking does not change the selected model.','SmallText'),p(summary['selection_reason']),p('The majority-class rule would achieve '+f'{(manifest[manifest.split=="test"].label=="Healthy").mean():.2%}'+' holdout accuracy. This is a reference calculation, not a seventh trained model.'),p('Practical trade-offs','Heading2'),p('Distance-based methods depend on feature scaling and dimensionality. Trees offer nonlinear decisions but can overfit. Ensembles reduce some instability at additional fitting cost. Timing here is descriptive because training workloads shared this computer; classifier latency excludes image decoding and feature extraction. No statistical superiority claim follows from point estimates or overlapping intervals.')])
    page(story,'6. Ethics / 7. AI Transparency / 8. Reflections')
    story.extend([p('6. Ethical Considerations and Bias Mitigation','Heading2'),p('Dataset labels describe image quality/health categories rather than verified disease diagnosis. A false-healthy result can mislead users; the interface exposes this limitation. Local uploads are decoded in memory and are not retained or used for training. Respect the original dataset terms before redistributing images.'),p('Class-weighting is used in Logistic Regression, SVM, Decision Tree, Random Forest and CNN. Macro-F1 and class recall avoid reporting majority-class accuracy alone. Grouped splits reduce duplicate leakage. These measures do not remove source/background bias, unknown plant identity, imperfect labels or absent external validation.'),p('7. AI Tool Usage Declaration and Transparency','Heading2'),p('OpenAI Codex assisted with inspecting the supplied briefs, restructuring code and notebooks, implementing tuning, creating visualizations, checking artifacts and drafting this report. Metrics and figures were computed by running code on the local dataset; no performance values were invented. The group must review and understand the generated work and declare AI use according to course policy. AI assistance is not evidence of individual student contribution.'),p('8. Reflections and Lessons Learned','Heading2'),p('Technical lessons from the implementation: identical splits are necessary for comparisons; preprocessing must be fitted inside validation folds; tuning must record failed or inferior choices as well as winners; deployment must use the exact training feature implementation. Search variety and model suitability matter more than listing many algorithms.'),p('A large training-validation gap indicates overfitting; reducing dimensions may help distance methods but can remove useful interactions. Search scores cannot justify claiming general improvement. A reused holdout and region-label confounding remain major limitations despite high point scores.'),p('These are implementation reflections, not attributed personal experiences. Before the viva, each member should explain their own notebook, parameter varieties, output files, errors and improvement proposals. The supplied requirement explicitly assesses individual demonstration.'),p('Next research steps: collect a prospective external set with plant IDs, healthy/unhealthy examples from each region and varied backgrounds; consider segmentation and calibrated confidence using development-only validation. These are proposed improvements, not completed experiments.')])
    page(story,'9. References and Reproduction')
    refs=["[1] Supplied course brief: final/Final Evaluation - Documentation.pdf. Nine report sections, maximum 15 pages, group-ID title.","[2] Supplied course brief: final/Final Evaluation - Implementation.pdf. Individual model/tuning evidence and comparison of six optimum individual models.","[3] Assigned dataset attribution recorded in project: IEEE DataPort, Leaves - India's Most Famous Basil Plant Leaves Quality Dataset. DOI: 10.21227/a4f6-4413. Source landing page unavailable during this review.","[4] scikit-learn official documentation, GridSearchCV. https://scikit-learn.org/stable/modules/generated/sklearn.model_selection.GridSearchCV.html (accessed 2026-09-27).","[5] scikit-learn official documentation, StratifiedGroupKFold. https://scikit-learn.org/stable/modules/generated/sklearn.model_selection.StratifiedGroupKFold.html (accessed 2026-09-27)."]
    story.extend(p(r) for r in refs)
    story.extend([p('Reproduce from zero','Heading2'),p('Install requirements.txt into a Python virtual environment. Place the four assigned labelled image folders under data/raw. Run python _run_all_training.py for all six models, or add --model MODEL_KEY for an individual model. Run python CNN/train_cnn.py for the separate CNN experiment. Generate both PDFs with python build_report.py --group-id '+group+'.'),p('Predict an image with python predict.py IMAGE --model MODEL_KEY, or run python app.py for the local selected-model demonstration. Each member notebook executes audit, feature extraction, tuning, evaluation, export and reload/inference.'),p('Evidence locations','Heading2'),p('parts/<model>/outputs/: tuning_results.csv, preprocessing_comparison.csv, search_space.json, model bundle, metrics, predictions, split manifest and evaluation.png.\noutputs/: shared audit, environment versions, selected deployment model and six_model_comparison.csv.\nCNN/: separate model, trial history, checkpoint, metrics and predictions.\nprogress/: preserved prior deliverables.\nfinal/: preserved assignment briefs.'),p('Dataset fingerprint: '+fingerprint,'SmallText'),p('Runtime: '+read(ROOT/'outputs'/'environment.json')['python'],'SmallText')])
    build(OUT/(group+'.pdf'),story)
    if classical_only:
        print('Created',OUT/(group+'.pdf'))
        return
    cnn=read(ROOT/'CNN'/'results'/'cnn_metrics.json')
    cm=pd.read_csv(ROOT/'CNN'/'analytics'/'dataset_manifest.csv')
    classical_test=manifest[manifest.split=='test'].sort_values('path')[['path','label','sha256']].reset_index(drop=True)
    cnn_test=cm[cm.role=='test'].sort_values('path')[['path','label','sha256']].reset_index(drop=True)
    if not classical_test.equals(cnn_test): raise ValueError('CNN holdout differs from classical holdout')
    cs=[]
    cs.extend([p(group+' - CNN Supplement','Title'),p('Separate from the six-model group comparison'),p('Design and complete pipeline','Heading1'),p('Raw audited RGB images -> common grouped holdout -> development train/validation split -> training-only horizontal/vertical flips -> normalization to [-1, 1] -> two Adam configurations -> validation checkpoint selection and early stopping -> holdout evaluation -> saved model -> single-image prediction.'),p('The network has four convolution blocks (32, 64, 128, 256 channels), each with BatchNorm, ReLU and max pooling. A 16,384-to-256 dense layer and two output logits follow dropout 0.4 and 0.3. Images are resized to 128 x 128. Class-weighted cross entropy addresses class frequency differences.'),p(f"Training / validation / holdout images: {cnn['n_train']} / {cnn['n_val']} / {cnn['n_test']}. Both classical and CNN holdouts were checked by image path, label and file hash. CNN uses fewer training images, a single validation split and a different representation, so scores are supplementary rather than a controlled architecture-only comparison."),p('Tuning evidence','Heading2'),table([['Trial','Learning rate','Weight decay','Epochs run','Best val F1'],*[[r['trial']+1,r['lr'],r['weight_decay'],r['epochs_run'],f"{r['best_val_macro_f1']:.4f}"] for r in cnn['tuning_trials']]],[60,110,110,100,111]),Spacer(1,8),p(f"At most {cnn['max_epochs']} epochs per trial; patience {cnn['early_stopping_patience']} without validation F1 improvement. ReduceLROnPlateau halves learning rate after two stagnant epochs. Best validation checkpoint is restored before test evaluation. Selected initial learning rate {cnn['learning_rate']}, weight decay {cnn['weight_decay']}. Total tuning time {cnn['fit_time_seconds']:.1f} seconds."),p('Reproduce: python CNN/train_cnn.py\nPredict: python predict.py IMAGE --model cnn\nEvidence: CNN/results/tuning_results.csv and CNN/analytics/all_trials_history.csv.')])
    page(cs,'CNN evaluation and visualizations')
    cs.extend([table([['Metric','Measured value'],['Holdout accuracy',f"{cnn['accuracy']:.2%}"],['Macro-F1',f"{cnn['macro_f1']:.4f}"],['Macro precision / recall',f"{cnn['precision']:.4f} / {cnn['recall']:.4f}"],['95% group-bootstrap F1',' - '.join(f'{x:.4f}' for x in cnn['bootstrap_95_ci'])]],[240,260]),Spacer(1,8),pic(ROOT/'CNN'/'analytics'/'training_curves.png',470),pic(ROOT/'CNN'/'analytics'/'confusion_matrix.png',280),p('Plots show the winning trial history and the restored checkpoint\'s holdout confusion matrix. Rows are true labels; columns are predictions. Bootstrap resampling uses perceptual groups (1,000 resamples).','SmallText')])
    page(cs,'CNN interpretation, limitations and transparency')
    cs.extend([p(f"The selected CNN achieves {cnn['accuracy']:.2%} holdout accuracy and {cnn['macro_f1']:.4f} macro-F1. It makes {cnn['confusion_matrix'][1][0]} false-healthy predictions and {cnn['confusion_matrix'][0][1]} false-unhealthy predictions."),p('Comparison context','Heading2'),p(f"The classical model selected by grouped CV is {summary['selected_model']}, with holdout macro-F1 {summary['metrics']['macro_f1']:.4f}. This contextual result is kept separate from the six-model ranking. Differences may reflect representation, training-set size, optimization, regularization and split variability; no significance claim is made."),p('Limitations and improvement proposals','Heading2'),p('Two settings are a small search, and early stopping may miss later improvements. Training uses a single seed and validation partition. The same previously evaluated holdout is reused. Perceptual groups are not verified plant IDs. A CNN can memorize backgrounds or capture conditions. Flips do not reproduce all field variation, and confidence is not calibrated.'),p('Collect external, plant-disjoint images before claiming deployment readiness. Additional seeds, wider development-only searches, segmentation and transfer learning are possible future experiments, not completed work.'),p('AI transparency and references','Heading2'),p('Codex assisted implementation, tuning orchestration, artifact checks and report drafting. Values are computed from saved predictions; group members must review and understand the work. Dataset attribution and course briefs are listed in the main group report. Implementation uses the installed PyTorch version '+cnn['torch_version']+'. Architecture and optimization settings are recorded in CNN/train_cnn.py and CNN/results/cnn_metrics.json.'),p('Saved output','Heading2'),p('CNN/outputs/cnn_model.pt stores the state dictionary, class order, image size and architecture identifier. predict.py recreates the same preprocessing and network before inference. Uploaded image content is not a model artifact and is never deserialized as weights.')])
    build(OUT/(group+'_CNN.pdf'),cs)
    print('Created',OUT/(group+'.pdf'),'and',OUT/(group+'_CNN.pdf'))

if __name__=='__main__':
    ap=argparse.ArgumentParser(); ap.add_argument('--group-id',default='abc'); ap.add_argument('--classical-only',action='store_true'); args=ap.parse_args()
    if not re.fullmatch(r'[A-Za-z0-9_-]+',args.group_id): ap.error('Use letters, digits, underscores or hyphens for group ID')
    main(args.group_id,args.classical_only)
